(window.webpackJsonp=window.webpackJsonp||[]).push([[38],{370:function(r,e,a){"use strict";a.r(e);var s=a(33),t=Object(s.a)({},function(){var r=this,e=r.$createElement,a=r._self._c||e;return a("ContentSlotsDistributor",{attrs:{"slot-key":r.$parent.slotKey}},[a("h2",{attrs:{id:"buller"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#buller","aria-hidden":"true"}},[r._v("#")]),r._v(" Buller")]),r._v(" "),a("p",[a("img",{attrs:{src:"https://lernia.itslearning.com/data/1821/C2568/Teori%20k%C3%A4lsvets%201/A3/A3%20bild%2018.JPG",alt:""}})]),r._v(" "),a("p",[r._v("Hantering av metalliska material går tyvärr inte att göra ljudlös.")]),r._v(" "),a("p",[r._v("Tidigare var hörselskador en vanlig yrkessjukdom hos människor som arbetade i verkstadsindustri, men med dagens resurser ska ingen svetsare/plåtslagare behöva bli hörselskadad.")]),r._v(" "),a("p",[r._v("Bullerbekämpning ska i första hand ske vid själva ljudkällan, dvs bullrande maskiner och arbetsoperationer skall byggas in eller avskärmas på annat sätt. Det som sedan återstår är att ta bort restbullret, och då måste tyvärr personlig skyddsutrustning tillgripas. Tyvärr, då all sådan utrustning blir en olägenhet för användaren.")]),r._v(" "),a("p",[r._v("Restbuller bekämpas bäst med hörselkåpor. Dessa ska vara anpassad för varje individ och användas vid allt arbete på bullrande arbetsplatser.")]),r._v(" "),a("p",[r._v("Vid lättare buller kan hörselproppar användas.")]),r._v(" "),a("p",[a("img",{attrs:{src:"https://lernia.itslearning.com/data/1821/C2568/Teori%20k%C3%A4lsvets%201/A3/A3%20bild%2019.JPG",alt:""}})]),r._v(" "),a("p",[r._v('Många arbetmoment i vårt yrke är starkt bullrande såsom mejsel-, slaggrensnings- och slipmaskiner. Riktning medför också oväsen liksom många andra arbetsuppgifter. Det går att undvika många bullerkällor. I stället för att slå bort saker kan de brytas bort. I stället för att använda bullrande "slaggpurror" kan slaggen avlägsnas med en slagghacka osv. Det är upp till den enskilde svetsaren/plåtslagaren att undvika buller.')]),r._v(" "),a("p",[r._v("Ljud mäts i decibel. Vid ca 85 db finns risk för hörselskador, och denna risk ökar därefter för varje högre decibeltal. Ljud som hammarslag mot en plåt uppfattas av de flesta som skadligt buller, men vad många inte tänker på, är att ljudet från t ex luftbågmejsling, plasmaskärning etc klart överstiger skadegränsen.")]),r._v(" "),a("p",[a("strong",[r._v("Det är därför enklast att använda hörselskydd vid allt arbete på verkstäder och byggarbetsplatser.")])]),r._v(" "),a("p",[a("strong",[r._v("Gränsvärden")]),a("br"),r._v("\nGränsvärdet för buller är 85 dB(A) räknat som medelvärde över en arbetsdag. 100 dB(A) under 15 minuter motsvarar 85 dB(A) under en hel arbetsdag. Dessutom finns ett insatsvärde på 80 dB(A). Utöver dessa värden finns också gränsvärden för impulsljud och maxinal ljudnivå. Mätningar för jämförelse med gränsvärden bör göras av någon med erfarenhet av bullermätningar, till exempel inom företagshälsovården."),a("br"),r._v("\nVid ljudnivåer över gränsvärdet ska hörselskydd användas. Vid insatsvärdet ska det finnas tillgång till hörselskydd.")]),r._v(" "),a("p",[a("img",{attrs:{src:"https://eu1files.itslearning.com/data/1821/627/Buller.png",alt:""}})])])},[],!1,null,null,null);e.default=t.exports}}]);